"""STANAG-4285 frame preamble sync finder (Tier B: public partial spec).

STANAG-4285's 80-symbol preamble contains about 2.5 repeats of a 31-bit
maximal-length PN sequence generated by the polynomial x^5 + x^2 + 1
(a 5-bit LFSR), used by the receiver to align each frame before the 8-PSK
data segments. Source: public technical summaries of the waveform (the
NATO standard itself is not publicly available, so only the confirmed
preamble PN sequence is implemented here -- not full 8-PSK
descrambling/demodulation of the 4 data + 3 channel-probe segments per
frame, which would need the full spec).

This gives a genuinely useful piece of the workflow even without the rest
of the spec: finding STANAG-4285 frame boundaries in a captured bitstream,
the same "locate the sync word" step the Graph view's Find dialog is for,
done automatically.
"""
from __future__ import annotations

import numpy as np

from sigint._bee.core.search import find_all
from sigint._bee.decoders.base import DecodeResult, Decoder
from sigint._bee.decoders.registry import register


def _generate_pn_sequence_x5_x2_1(length: int = 31, init: int = 1) -> np.ndarray:
    """5-bit Fibonacci LFSR for the primitive polynomial x^5 + x^2 + 1.

    Register bits [b0..b4] (b0 = output tap), feedback = b4 XOR b1, shifted
    in at b0 each step (standard Fibonacci/external-XOR LFSR form). This
    specific polynomial is a known primitive polynomial over GF(2), so this
    construction is guaranteed maximal-length (period 2^5-1 = 31); verified
    in tests/test_stanag4285.py by checking the period and the 16/15
    ones/zeros balance property of a true m-sequence.
    """
    state = init & 0x1F or 1
    bits = []
    for _ in range(length):
        b0 = state & 1
        bits.append(b0)
        feedback = b0 ^ ((state >> 3) & 1)  # b0 XOR b3, i.e. taps at x^5/x^2
        state = (state >> 1) | (feedback << 4)
    return np.array(bits, dtype=np.uint8)


PN_SEQUENCE = _generate_pn_sequence_x5_x2_1()


class Stanag4285Decoder(Decoder):
    name = "Stanag - 4285"
    description = "Finds the 31-bit preamble PN sequence (x^5+x^2+1); no data demod"

    def decode(self, bits: np.ndarray, block=None) -> DecodeResult:
        matches = find_all(bits, PN_SEQUENCE, max_err_bits=2)
        lines = [f"preamble PN sync at bit {pos} (errors={err})" for pos, err in matches[:200]]
        return DecodeResult(
            text="\n".join(lines),
            symbol_count=len(matches),
            error_count=0,
            notes="preamble sync search only -- see module docstring for scope",
        )


for _name in ("Stanag - 4285", "Stanag-4285"):
    _decoder = Stanag4285Decoder()
    _decoder.name = _name
    register(_decoder)
